struct Outcome {
  std::vector<std::string> trace;
  unsigned increments = 0, decrements = 0;
  unsigned repeatedIncrements = 0, repeatedDecrements = 0;
  unsigned lockEntries = 0, messages = 0, destructions = 0;
};

static UID resourceId(const D3DAutoPtr& ptr) { return *ptr ? (*ptr)->getId() : 0; }

static void stateSnapshot(const BaseDirect3DDevice9Ex_LSS::State& state, std::ostringstream& text) {
  text << " idx=" << resourceId(state.indices);
  for (size_t i = 0; i < state.streams.size(); ++i) {
    text << " vb" << i << '=' << resourceId(state.streams[i]) << ',' << state.streamOffsets[i] << ',' << state.streamStrides[i];
  }
  text << " other=" << state.renderStates[0] << ',' << state.material << ',' << state.vertexConstants.fConsts[0];
}

static void snapshot(const char* label, BaseDirect3DDevice9Ex_LSS& device,
                     std::initializer_list<D3DRefCounted*> resources,
                     Direct3DStateBlock9_LSS* block = nullptr) {
  std::ostringstream text;
  text << "snapshot:" << label;
  stateSnapshot(device.m_state, text);
  if (block) {
    text << " capture:";
    stateSnapshot(block->m_captureState, text);
    text << " dirty=" << block->m_dirtyFlags.indices;
    for (size_t i = 0; i < block->m_dirtyFlags.streams.size(); ++i) {
      text << ',' << block->m_dirtyFlags.streams[i] << ',' << block->m_dirtyFlags.streamOffsetsAndStrides[i];
    }
  }
  if (device.m_dataKnown) {
    text << " known=" << device.m_dataKnown->indices;
    for (bool value : device.m_dataKnown->streams) text << ',' << value;
  } else {
    text << " known=absent";
  }
  for (const auto* resource : resources) {
    text << " ref" << resource->getId() << '=' << resource->objectRefs << ',' << resource->externalRefs << ',' << resource->dead;
  }
  text << " locks=" << active->lockEntries << ',' << active->lockDepth;
  active->semantic.push_back(text.str());
}

template<typename F> HRESULT invokeSetter(F&& fn) {
  require(!active->setterActive, "unexpected nested setter");
  active->setterActive = true;
  const auto hr = fn();
  active->setterActive = false;
  require(active->lockDepth == 0, "setter left lock held");
  active->semantic.push_back("hresult:" + std::to_string(hr));
  return hr;
}

template<typename Device> Outcome runCases(bool diagnostics) {
  Context context;
  active = &context;
  l4d2_data::enabled.store(diagnostics);
  Direct3DVertexBuffer9_LSS va(11), vb(12), soleVertex(31);
  Direct3DIndexBuffer9_LSS ia(21), ib(22), soleIndex(41);
  auto resources = { static_cast<D3DRefCounted*>(&va), static_cast<D3DRefCounted*>(&vb),
    static_cast<D3DRefCounted*>(&ia), static_cast<D3DRefCounted*>(&ib),
    static_cast<D3DRefCounted*>(&soleVertex), static_cast<D3DRefCounted*>(&soleIndex) };
  Outcome result;
  {
    Device d;
    d.m_dataKnown = std::make_unique<BaseDirect3DDevice9Ex_LSS::StateCaptureDirtyFlags>();
    auto stream = [&](UINT slot, IDirect3DVertexBuffer9* ptr, UINT offset, UINT stride) {
      return invokeSetter([&] { return d.SetStreamSource(slot, ptr, offset, stride); });
    };
    auto index = [&](IDirect3DIndexBuffer9* ptr) {
      return invokeSetter([&] { return d.SetIndices(ptr); });
    };
    // First / duplicate / changed metadata / independent stream ownership.
    require(stream(0, &va, 8, 24) == S_OK && index(&ia) == S_OK, "first binding failed");
    snapshot("first", d, resources);
    stream(0, &va, 8, 24); index(&ia);
    snapshot("identical", d, resources);
    stream(0, &va, 20, 24);
    require(d.m_state.streamOffsets[0] == 20, "same resource lost offset update");
    stream(0, &va, 20, 32);
    require(d.m_state.streamStrides[0] == 32, "same resource lost stride update");
    stream(1, &va, 40, 48);
    require(va.objectRefs == 3, "independent slot lost ownership");
    snapshot("metadata-and-slots", d, resources);

    // Resource changes must acquire the replacement before releasing old.
    const auto eventStart = context.refEvents.size();
    stream(0, &vb, 4, 16);
    require(context.refEvents.size() == eventStart + 2 && context.refEvents[eventStart] == "+12"
            && context.refEvents[eventStart + 1] == "-11", "changed VB acquire/release order changed");
    const auto indexEventStart = context.refEvents.size();
    index(&ib);
    require(context.refEvents.size() == indexEventStart + 2 && context.refEvents[indexEventStart] == "+22"
            && context.refEvents[indexEventStart + 1] == "-21", "changed IB acquire/release order changed");
    snapshot("changed-resource", d, resources);

    stream(0, nullptr, 999, 999); index(nullptr);
    require(d.m_state.streamOffsets[0] == 4 && d.m_state.streamStrides[0] == 16,
            "null binding changed cached metadata");
    stream(0, nullptr, 1000, 1000); index(nullptr);
    snapshot("repeated-null", d, resources);
    stream(1, nullptr, 0, 0);
    stream(0, &va, 8, 24); index(&ia);

    // DrawUP in production clears the Host binding while the Client retains
    // its pointer. Model only that documented effect; the next real setters
    // must still emit the commands needed to bind the resource again.
    context.hostStream0 = 0; context.hostIndex = 0;
    context.semantic.push_back("simulated-DrawIndexedPrimitiveUP-clears-host");
    stream(0, &va, 8, 24); index(&ia);
    require(context.hostStream0 == va.id && context.hostIndex == ia.id,
            "identical rebind failed to restore Host after DrawUP");
    snapshot("drawup-rebind", d, resources);

    // Diagnostic storage is not an authority for object ownership.
    d.invalidateDataState();
    stream(0, &va, 8, 24); index(&ia);
    d.m_dataKnown.reset();
    stream(0, &va, 12, 28); index(&ia);
    snapshot("diagnostic-state-absent", d, resources);
    d.m_dataKnown = std::make_unique<BaseDirect3DDevice9Ex_LSS::StateCaptureDirtyFlags>();

    {
      Direct3DStateBlock9_LSS block(&d);
      d.m_stateRecording = &block;
      // Live already matches but capture is empty: capture needs its own ref.
      stream(0, &va, 12, 28); index(&ia);
      require(resourceId(block.m_captureState.streams[0]) == va.id &&
              resourceId(block.m_captureState.indices) == ia.id,
              "recording compared wrong ownership domain");
      require(va.objectRefs == 3 && ia.objectRefs == 3, "StateBlock missing independent reference");
      snapshot("record-first", d, resources, &block);

      // Even a prefilled equal capture with clean flags must become dirty.
      block.m_dirtyFlags = {};
      stream(0, &va, 16, 36); index(&ia);
      require(block.m_dirtyFlags.streams[0] && block.m_dirtyFlags.streamOffsetsAndStrides[0]
              && block.m_dirtyFlags.indices, "equal capture lost dirty flags");
      require(block.m_captureState.streamOffsets[0] == 16 && block.m_captureState.streamStrides[0] == 36,
              "recording lost changed metadata");
      snapshot("record-prefilled-clean", d, resources, &block);

      block.m_dirtyFlags = {};
      stream(0, nullptr, 100, 100); index(nullptr);
      require(block.m_dirtyFlags.streams[0] && block.m_dirtyFlags.indices
              && !block.m_dirtyFlags.streamOffsetsAndStrides[0], "record null dirty flags changed");
      require(block.m_captureState.streamOffsets[0] == 16 && block.m_captureState.streamStrides[0] == 36,
              "record null unexpectedly changed metadata");
      stream(0, nullptr, 101, 101); index(nullptr);
      require(block.Capture() == D3DERR_INVALIDCALL, "Capture while recording must fail");
      stream(0, &va, 16, 36); index(&ia);
      d.m_stateRecording = nullptr;
      stream(0, &vb, 44, 52); index(&ib);
      require(block.Apply() == S_OK, "real StateBlock Apply failed");
      require(resourceId(d.m_state.streams[0]) == va.id && resourceId(d.m_state.indices) == ia.id
              && d.m_state.streamOffsets[0] == 16 && d.m_state.streamStrides[0] == 36,
              "real StateTransfer failed binding Apply");
      require(!d.m_dataKnown->streams[0] && !d.m_dataKnown->indices, "Apply failed to invalidate diagnostics");
      stream(0, &va, 16, 36); index(&ia);
      snapshot("stateblock-apply-then-equal", d, resources, &block);

      // Actual Capture copies into independently owned storage, including
      // selected unrelated fields, so future Apply has the real transfer path.
      stream(0, &vb, 60, 64); index(&ib);
      d.m_state.renderStates[0] = 501; d.m_state.material = 502; d.m_state.vertexConstants.fConsts[0] = 503;
      block.m_dirtyFlags.renderStates[0] = true;
      block.m_dirtyFlags.material = true; block.m_dirtyFlags.vertexConstants.fConsts[0] = true;
      require(block.Capture() == S_OK, "real StateBlock Capture failed");
      stream(0, &va, 16, 36); index(&ia);
      d.m_state.renderStates[0] = 0; d.m_state.material = 0; d.m_state.vertexConstants.fConsts[0] = 0;
      block.Apply();
      require(resourceId(d.m_state.streams[0]) == vb.id && resourceId(d.m_state.indices) == ib.id
              && d.m_state.renderStates[0] == 501 && d.m_state.material == 502
              && d.m_state.vertexConstants.fConsts[0] == 503, "Capture/Apply round trip changed state");
      snapshot("capture-roundtrip", d, resources, &block);
    }
    snapshot("block-destroyed", d, resources);

    // Keep Host error / timeout behavior intact even for duplicate bindings.
    context.responses = true;
    for (HRESULT expected : { S_OK, HOST_FAILURE }) {
      context.response = expected;
      require(stream(0, &vb, 60, 64) == expected && index(&ib) == expected, "duplicate lost Host HRESULT");
    }
    context.timeout = true;
    require(stream(0, &vb, 60, 64) == D3DERR_INVALIDCALL && index(&ib) == D3DERR_INVALIDCALL,
            "duplicate lost timeout fallback");
    context.responses = false;
    require(stream(0, &vb, 60, 64) == S_OK && index(&ib) == S_OK, "disabled optional response changed");
    context.timeout = false; context.response = S_OK;

    // Duplicate bindings while external refs are gone must preserve lifetime.
    stream(0, &soleVertex, 80, 88); index(&soleIndex);
    soleVertex.dropExternal(); soleIndex.dropExternal();
    require(soleVertex.objectRefs == 1 && soleIndex.objectRefs == 1, "sole internal ownership setup failed");
    stream(0, &soleVertex, 80, 88); index(&soleIndex);
    require(!soleVertex.dead && !soleIndex.dead, "equal binding destroyed sole-owned resource");
    {
      Direct3DStateBlock9_LSS block(&d);
      block.m_dirtyFlags.streams[0] = block.m_dirtyFlags.streamOffsetsAndStrides[0] = true;
      block.m_dirtyFlags.indices = true;
      block.Capture();
      stream(0, nullptr, 0, 0); index(nullptr);
      require(soleVertex.objectRefs == 1 && soleIndex.objectRefs == 1, "StateBlock did not retain after unbind");
      block.Apply();
      stream(0, &soleVertex, 80, 88); index(&soleIndex);
      snapshot("sole-owned-after-apply", d, resources, &block);
    }
    stream(0, &soleVertex, 80, 88); index(&soleIndex);
    snapshot("sole-owned-block-gone", d, resources);
    stream(0, nullptr, 0, 0); index(nullptr);
    require(soleVertex.dead && soleIndex.dead, "final unbind did not destroy resources");

    // Count actual D3DAutoPtr operations for 1000 equal VB and IB calls.
    stream(0, &va, 8, 24); index(&ia);
    const auto beforeIncrements = context.increments, beforeDecrements = context.decrements;
    for (unsigned n = 0; n < 1000; ++n) { stream(0, &va, 8, 24); index(&ia); }
    result.repeatedIncrements = context.increments - beforeIncrements;
    result.repeatedDecrements = context.decrements - beforeDecrements;
    snapshot("repeated-workload", d, resources);
  }
  va.dropExternal(); vb.dropExternal(); ia.dropExternal(); ib.dropExternal();
  require(context.violations == 0, "lifetime/locking violations: " + std::to_string(context.violations));
  require(context.destructionCount == 6, "resources not destroyed exactly once");
  for (const auto* resource : resources) require(resource->dead && !resource->objectRefs && !resource->externalRefs,
                                                "resource still owned after device teardown");
  result.increments = context.increments; result.decrements = context.decrements;
  result.lockEntries = context.lockEntries; result.destructions = context.destructionCount;
  for (const auto& line : context.semantic) if (line.rfind("message:", 0) == 0) ++result.messages;
  result.trace = std::move(context.semantic);
  active = nullptr;
  return result;
}

template<bool Sync> void compare(bool diagnostics) {
  const auto baseline = runCases<BaselineDevice<Sync>>(diagnostics);
  const auto candidate = runCases<CandidateDevice<Sync>>(diagnostics);
  if (baseline.trace != candidate.trace) {
    const auto bound = (std::min)(baseline.trace.size(), candidate.trace.size());
    for (size_t i = 0; i < bound; ++i) {
      if (baseline.trace[i] != candidate.trace[i]) {
        throw std::runtime_error("semantic trace mismatch at " + std::to_string(i) + ": " + baseline.trace[i] + " vs " + candidate.trace[i]);
      }
    }
    throw std::runtime_error("semantic trace length mismatch");
  }
  require(baseline.repeatedIncrements == 2000 && baseline.repeatedDecrements == 2000,
          "baseline duplicate operation count differs");
  require(candidate.repeatedIncrements == 0 && candidate.repeatedDecrements == 0,
          "candidate retains/releases on equal ownership");
  require(candidate.increments < baseline.increments && candidate.decrements < baseline.decrements,
          "candidate did not reduce ownership work");
  std::cout << "PASS sync=" << Sync << " diagnostics=" << diagnostics
            << " semantic_records=" << candidate.trace.size() << " messages=" << candidate.messages
            << " lock_entries=" << candidate.lockEntries << " destructions=" << candidate.destructions
            << " total_inc=" << baseline.increments << "->" << candidate.increments
            << " total_dec=" << baseline.decrements << "->" << candidate.decrements
            << " repeated_2000_setters_inc_dec=2000/2000->0/0\n";
}

template<typename Device> void rejectMutant(const char* label) {
  bool rejected = false;
  try { (void)runCases<Device>(true); }
  catch (const std::exception& error) { rejected = true; std::cout << "NEGATIVE_CONTROL " << label << " rejected: " << error.what() << '\n'; }
  active = nullptr;
  require(rejected, std::string("test failed to detect mutant: ") + label);
}

int main() {
  try {
    compare<false>(false); compare<false>(true);
    compare<true>(false); compare<true>(true);
    rejectMutant<SkipCommandMutant<true>>("skip-command");
    rejectMutant<WrongDomainMutant<true>>("compare-live-during-recording");
    rejectMutant<MissingDirtyMutant<true>>("omit-recording-dirty");
    rejectMutant<MissingMetadataMutant<true>>("omit-offset-stride");
    std::cout << "ALL PASS: functional adapter tests; no timing or FPS claims\n";
    return 0;
  } catch (const std::exception& error) {
    std::cerr << "FAIL: " << error.what() << '\n';
    return 1;
  }
}
